function safePreview(html: string) {
  // Parse inertly, then place the policy before all supplied markup. The iframe remains a unique origin.
  const policy = `<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; font-src data:; connect-src 'none'; form-action 'none'; base-uri 'none'"><meta name="referrer" content="no-referrer">`;
  const parsed = new DOMParser().parseFromString(html, 'text/html');
  parsed.querySelectorAll('meta[http-equiv="refresh" i], base').forEach((node) => node.remove());
  parsed.head.insertAdjacentHTML('afterbegin', policy);
  return '<!doctype html>' + parsed.documentElement.outerHTML;
}

