function Modal({ children, title, eyebrow, onClose, wide = false }: { children: ReactNode; title: string; eyebrow?: string; onClose: () => void; wide?: boolean }) {
  const ref = useRef<HTMLDivElement>(null);
  const closeRef = useRef(onClose); closeRef.current = onClose;
  useEffect(() => {
    const before = document.activeElement as HTMLElement | null;
    const focusable = () => [...(ref.current?.querySelectorAll<HTMLElement>('button:not([disabled]), input, textarea, select, [tabindex="0"]') || [])];
    focusable()[0]?.focus();
    function onKey(event: KeyboardEvent) {
      if (event.key === 'Escape') closeRef.current();
      if (event.key === 'Tab') {
        const items = focusable(); const first = items[0]; const last = items[items.length - 1];
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
      }
    }
    document.addEventListener('keydown', onKey);
    return () => { document.removeEventListener('keydown', onKey); before?.focus(); };
  }, []);
  return createPortal(<div className="ws-modal-backdrop" onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}><div className={`ws-modal ${wide ? 'ws-modal-wide' : ''}`} role="dialog" aria-modal="true" aria-label={title} ref={ref}><header className="ws-modal-header"><div>{eyebrow && <span className="ws-eyebrow">{eyebrow}</span>}<h2>{title}</h2></div><button className="ws-icon-button" aria-label="Close dialog" onClick={onClose}><X size={19} /></button></header><div className="ws-modal-body">{children}</div></div></div>, document.body);
}

