      if (inputs.length > 12000) { notify('The plan inputs have reached their limit. Review and shorten the plan before adding more notes.'); return; }
      const saved = change((p) => ({ ...p, stage: 'draft', state: { ...p.state, plan: { ...planOf(p), inputs, status: 'draft' }, messages: [...p.state.messages, { id: uid(), role: 'user', text: request, time: now() }, { id: uid(), role: 'assistant', text: 'Added your note to the plan inputs. The plan is a draft, and source files have not changed. Review the plan, approve it, then choose Simulate build.', time: now() }] } }));
