    if (fromPlan) close();
    setPrompt(''); setRun({ kind: 'build', step: 0 });
    message(request, 'user');
    if (!(await pause(550))) return; setRun({ kind: 'build', step: 1 });
    if (!(await pause(650))) return; setRun({ kind: 'build', step: 2 });
    if (!(await pause(650))) return;
    const saved = change((p) => {
      const entry = previewEntry(p);
      let source = entry?.content || createWorkspacePreview(p);
      const lower = request.toLowerCase();
      if (/dark/.test(lower)) source = addPreviewStyle(source, 'body{background:#141b21!important;color:#e7eceb!important}header,.card,.stat,.box{background:#1d2730!important;border-color:#303c47!important}textarea{background:#1d2730!important;color:#e7eceb!important}p,small{color:#a4b1bb!important}h1,h2,b,strong{color:inherit}');
      else if (/green|mint/.test(lower)) source = addPreviewStyle(source, 'body{background:#eff8f1!important;color:#294b36!important}button,.primary{background:#277953!important;color:#fff!important}.card,.box,.stat,header{border-color:#cfe2d2!important}.tag,.mark{background:#deefdf!important;color:#42784c!important}');
      else if (/light/.test(lower)) source = addPreviewStyle(source, 'body{background:#f7f8fa!important;color:#1f2937!important}header,.card,.stat,.box,textarea{background:white!important;border-color:#e5e8ef!important;color:#1f2937!important}');
      else {
        const addition = `<section style="max-width:976px;margin:20px auto 38px;padding:25px;background:#fff;border:1px solid #e5e8ef;border-radius:12px;color:#27332d"><small style="color:#277953;font-size:10px;letter-spacing:1px;text-transform:uppercase">Prototype addition</small><h2 style="font-size:20px;margin:12px 0">${escapeHtml(request.slice(0, 100))}</h2><p style="color:#858d89">This sample section captures your request. Connect a generation provider to implement arbitrary application logic.</p><button style="padding:10px 16px;border:0;background:#277953;color:white;border-radius:7px;cursor:pointer" onclick="this.textContent='Sample action completed';this.disabled=true">Try sample action</button></section>`;
        source = /<\/body>/i.test(source) ? source.replace(/<\/body>/i, addition + '</body>') : source + addition;
      }
      return { ...p, stage: 'ready', state: { ...p.state, files: putFile(p.state.files, entry?.path || 'index.html', source), versions: recordVersion(p, `Before: ${request.slice(0, 54)}`), messages: [...p.state.messages, { id: uid(), role: 'assistant', time: now(), text: `Simulation complete. ${fromPlan ? 'You chose to build the reviewed plan. ' : ''}I updated the actual preview source ${/dark|light|green|mint/.test(lower) ? 'with your requested appearance' : 'with a sample section for your request'}. You can interact with it, edit the code, or check version history for retained checkpoints.\n\nThis is a scripted prototype, not an AI-generated implementation.${fromPlan ? ' The plan describes the intended behavior; this sample does not implement its full agent workflow.' : ''}` }] } };
    });
    setRun(null); if (!saved) return; setTab('preview'); setFileDraft(null); notify(current.current.state.versions.length ? 'Preview updated. The previous source is retained in version history.' : 'Preview updated. No checkpoint fits alongside this app; export source before future changes.');
